private func applyStageSwitch(hide hiddenIDs: Set<WindowID>, show members: [PersistentStageMember], on display: DisplaySnapshot, snapshot: DaemonSnapshot, windowsByID: [WindowID: WindowSnapshot]) -> Int {
    var applied = 0
    for id in hiddenIDs {
        guard let window = windowsByID[id] else { continue }
        if service.setFrame(HiddenWindowPlacement.frame(for: window.frame.cgRect, on: display, among: snapshot.displays), of: window) != nil { applied += 1 }
    }
    for member in members {
        guard let window = windowsByID[member.windowID] else { continue }
        if service.setFrame(member.frame.cgRect, of: window) != nil { applied += 1 }
    }
    return applied
}

